scenario.en:
const BUCKETS = 4096;
const sessions = loadActiveSessions();   // 120_000 live entries

const table = new Array(BUCKETS).fill(0);
for (const s of sessions) {
  table[hash(s.id) % BUCKETS]++;
}
const worst = Math.max(...table);
// alert fires when worst > 25
// ticket: "replace hash() with a better one so the alert stops"

